<?php
require __DIR__.'/sales.php';
require_once APPPATH.'services/NativeCompanySalesDates.php';
$forms=new NativeCompanySalesSettings($db,$p);$dates=new NativeCompanySalesDates($db,$p);$store=new CompanySettingsStorage($db,$p);$start=$GLOBALS['essentialChecks'];
$before=$db->query('SELECT * FROM '.$p.'company_sales_documents ORDER BY id')->result_array();
$store->mutate($a,7,'update','dateformat','d/m/Y|%d/%m/%Y');
$store->mutate($b,7,'update','dateformat','m-d-Y|%m-%d-%Y');
$eA=$forms->page($a,7,'estimates');$v=$eA['values'];$v['estimate_due_after']='2';$forms->save($a,7,'estimates',$eA['revision'],$v);
$eB=$forms->page($b,7,'estimates');$v=$eB['values'];$v['estimate_due_after']='0';$forms->save($b,7,'estimates',$eB['revision'],$v);
